38	inline int32_t CeilDivI32(int32_t a, int32_t b)
39	{
40	    if (b == 0) { return 0; }
41	    return (a + b - 1) / b;
42	}
43	
44	int64_t CeilDiv(int64_t value, int64_t factor)
45	{
46	    if (factor == 0) {
47	        return 0;
48	    }
49	    if (value % factor == 0) {
50	        return value / factor;
51	    }
52	    return value / factor + 1;
53	}
54	
55	c10::SmallVector<int64_t, 3> avg_pool3d_output_size(const at::Tensor &self, c10::IntArrayRef kernel_size,
56	                                                    c10::IntArrayRef stride, c10::IntArrayRef padding,
57	                                                    bool ceil_mode)
58	{
59	    int self_d = self.size(-3);
60	    int self_h = self.size(-2);
61	    int self_w = self.size(-1);
62	
63	    int64_t kernel_d = ceil_mode ? (CeilDiv(self_d + 2 * padding[0] - kernel_size[0], stride[0]) + 1)
64	                                 : ((self_d + 2 * padding[0] - kernel_size[0]) / stride[0] + 1);
65	    int64_t kernel_h = ceil_mode ? (CeilDiv(self_h + 2 * padding[1] - kernel_size[1], stride[1]) + 1)
66	                                 : ((self_h + 2 * padding[1] - kernel_size[1]) / stride[1] + 1);
67	    int64_t kernel_w = ceil_mode ? (CeilDiv(self_w + 2 * padding[2] - kernel_size[2], stride[2]) + 1)
68	                                 : ((self_w + 2 * padding[2] - kernel_size[2]) / stride[2] + 1);
69	
70	    if (ceil_mode) {
71	        if ((kernel_d - 1) * stride[0] >= self_d + padding[0]) {
72	            --kernel_d;
73	        }
74	        if ((kernel_h - 1) * stride[1] >= self_h + padding[1]) {
75	            --kernel_h;
76	        }
77	        if ((kernel_w - 1) * stride[2] >= self_w + padding[2]) {
78	            --kernel_w;
79	        }
80	    }
81	
82	    c10::SmallVector<int64_t, 3> output_size;
83	    if (self.dim() == 4) {
84	        output_size = {self.size(0), kernel_d, kernel_h, kernel_w};
85	    } else {
86	        output_size = {self.size(0), self.size(1), kernel_d, kernel_h, kernel_w};
87	    }
88	    return output_size;
89	}
