// Stream the int32 tiling blob from GM into the on-stack tiling struct.
template <typename T>
__aicore__ inline void CopyTiling(T *tiling, GM_ADDR tilingGM)
{
    int32_t *dst = reinterpret_cast<int32_t *>(tiling);
    auto *src = reinterpret_cast<__gm__ int32_t *>(tilingGM);
    for (size_t i = 0; i < sizeof(T) / sizeof(int32_t); ++i) {
        dst[i] = src[i];
    }
}

// Effective averaging divisor for the output position (od, oh, ow), matching
// torch.nn.functional.avg_pool3d semantics:
//   - divisor_override (if > 0) wins.
//   - count_include_pad -> full kD*kH*kW window.
//   - otherwise -> number of input elements actually inside [0, D)x[0, H)x[0, W).
__aicore__ inline int ComputeDivisor(int od, int oh, int ow, const AvgPool3DTiling &t)
{
    if (t.divisorOverride > 0) {
        return t.divisorOverride;
    }
    if (t.countIncludePad > 0) {
        return t.kD * t.kH * t.kW;
    }

    const int dStart = od * t.sD - t.pD;
    const int hStart = oh * t.sH - t.pH;
    const int wStart = ow * t.sW - t.pW;

    const int dBegin = dStart < 0 ? 0 : dStart;
    const int hBegin = hStart < 0 ? 0 : hStart;
    const int wBegin = wStart < 0 ? 0 : wStart;

    int dEnd = dStart + t.kD;
    int hEnd = hStart + t.kH;
    int wEnd = wStart + t.kW;
    if (dEnd > t.D) { dEnd = t.D; }
    if (hEnd > t.H) { hEnd = t.H; }
    if (wEnd > t.W) { wEnd = t.W; }

    const int validD = dEnd > dBegin ? (dEnd - dBegin) : 0;
    const int validH = hEnd > hBegin ? (hEnd - hBegin) : 0;
    const int validW = wEnd > wBegin ? (wEnd - wBegin) : 0;
    return validD * validH * validW;
}

#endif  // AVG_POOL3D_KERNEL_COMMON_H
