#include "kernel_operator.h"
#include "kernel_common.h"
#include "avg_pool3d_tiling.h"

namespace {
constexpr int32_t BUFFER_NUM = 2;
}

// AvgPool3d generic kernel.
//
// Layout: input is viewed as x[(N * D * H * W), C], output as y[(N * OD * OH * OW), C]
// in NDHWC layout (channel last, contiguous).  Each AI core handles a strided
// subset of the N*outSpatial output rows.  For each output row, it accumulates
// every valid input row in the kD x kH x kW window across the C-channel vector,
// then divides by the effective window divisor.
//
// FP16 / BF16 inputs are cast up to FP32 for accumulation and cast back to the
// output dtype on store.  FP32 inputs accumulate directly.
template <typename T>
class KernelAvgPool3D {
public:
    __aicore__ inline KernelAvgPool3D() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR tilingGM, AscendC::TPipe *pipe)
    {
        CopyTiling(&tiling_, tilingGM);

        xGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x),
                             static_cast<uint64_t>(tiling_.N) * tiling_.inSpatial * tiling_.C);
        yGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(y),
                             static_cast<uint64_t>(tiling_.N) * tiling_.outSpatial * tiling_.C);

        if ASCEND_IS_AIV {
            pipe_ = pipe;
            vecLen_ = tiling_.vectorLen > 0 ? tiling_.vectorLen : tiling_.C;
            if (vecLen_ > tiling_.C) {
                vecLen_ = tiling_.C;
            }

            pipe_->InitBuffer(inQueue_, BUFFER_NUM, static_cast<uint32_t>(vecLen_ * sizeof(T)));
            pipe_->InitBuffer(outQueue_, BUFFER_NUM, static_cast<uint32_t>(vecLen_ * sizeof(T)));
            pipe_->InitBuffer(accBuf_, static_cast<uint32_t>(vecLen_ * sizeof(float)));
            // FP16/BF16 needs a temp FP32 buffer to hold the cast of each loaded slice.
            if constexpr (!std::is_same_v<T, float>) {
                pipe_->InitBuffer(castBuf_, static_cast<uint32_t>(vecLen_ * sizeof(float)));
            }
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int workerId = static_cast<int>(AscendC::GetBlockIdx());
            int workerCount = tiling_.launchBlocks;
            if (workerCount <= 0) {
                workerCount = 1;
            }
            const int totalRows = tiling_.N * tiling_.outSpatial;
            for (int outRow = workerId; outRow < totalRows; outRow += workerCount) {
                ProcessOneRow(outRow);
            }
        }
    }

private:
    __aicore__ inline void AccumulateSlice(int inRow, int cBase, int cLen,
                                           AscendC::LocalTensor<float> &accLocal)
    {
        AscendC::LocalTensor<T> inLocal = inQueue_.AllocTensor<T>();
        AscendC::DataCopyExtParams copyParams{
            1, static_cast<uint32_t>(cLen * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<T> padParams{false, 0, 0, 0};
        AscendC::DataCopyPad(inLocal,
                             xGm_[static_cast<uint64_t>(inRow) * tiling_.C + cBase],
                             copyParams, padParams);
        inQueue_.EnQue(inLocal);
        inLocal = inQueue_.DeQue<T>();
        if constexpr (std::is_same_v<T, float>) {
            AscendC::Add(accLocal, accLocal, inLocal, cLen);
        } else {
            AscendC::LocalTensor<float> castLocal = castBuf_.Get<float>();
            AscendC::Cast(castLocal, inLocal, AscendC::RoundMode::CAST_NONE, cLen);
            AscendC::Add(accLocal, accLocal, castLocal, cLen);
        }
        inQueue_.FreeTensor(inLocal);
    }

    __aicore__ inline void AccumulateWindow(int nIdx, int od, int oh, int ow, int cBase, int cLen,
                                            AscendC::LocalTensor<float> &accLocal)
    {
        for (int kd = 0; kd < tiling_.kD; ++kd) {
            const int idVal = od * tiling_.sD - tiling_.pD + kd;
            if (idVal < 0 || idVal >= tiling_.D) {
                continue;
            }
            for (int kh = 0; kh < tiling_.kH; ++kh) {
                const int ihVal = oh * tiling_.sH - tiling_.pH + kh;
                if (ihVal < 0 || ihVal >= tiling_.H) {
                    continue;
                }
                for (int kw = 0; kw < tiling_.kW; ++kw) {
                    const int iwVal = ow * tiling_.sW - tiling_.pW + kw;
                    if (iwVal < 0 || iwVal >= tiling_.W) {
                        continue;
                    }
                    const int inRow = nIdx * tiling_.inSpatial
                                      + idVal * tiling_.hw + ihVal * tiling_.W + iwVal;
                    AccumulateSlice(inRow, cBase, cLen, accLocal);
                }
            }
        }
    }

    __aicore__ inline void StoreOutput(int outRow, int cBase, int cLen, int divisor,
                                       AscendC::LocalTensor<float> &accLocal)
    {
        AscendC::LocalTensor<T> outLocal = outQueue_.AllocTensor<T>();
        if (divisor <= 0) {
            if constexpr (std::is_same_v<T, float>) {
                AscendC::Duplicate(outLocal, 0.0f, cLen);
            } else {
                AscendC::LocalTensor<float> tmp = castBuf_.Get<float>();
                AscendC::Duplicate(tmp, 0.0f, cLen);
                AscendC::Cast(outLocal, tmp, AscendC::RoundMode::CAST_RINT, cLen);
            }
        } else {
            const float invDiv = 1.0f / static_cast<float>(divisor);
            if constexpr (std::is_same_v<T, float>) {
                AscendC::Muls(outLocal, accLocal, invDiv, cLen);
            } else {
                AscendC::LocalTensor<float> tmp = castBuf_.Get<float>();
                AscendC::Muls(tmp, accLocal, invDiv, cLen);
                AscendC::Cast(outLocal, tmp, AscendC::RoundMode::CAST_RINT, cLen);
            }
        }
        outQueue_.EnQue(outLocal);
        outLocal = outQueue_.DeQue<T>();
        AscendC::DataCopyExtParams copyParams{
            1, static_cast<uint32_t>(cLen * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPad(yGm_[static_cast<uint64_t>(outRow) * tiling_.C + cBase],
                             outLocal, copyParams);
        outQueue_.FreeTensor(outLocal);
    }

    __aicore__ inline void ProcessOneRowChunk(int nIdx, int od, int oh, int ow,
                                              int outRow, int cBase, int cLen, int divisor)
    {
        AscendC::LocalTensor<float> accLocal = accBuf_.Get<float>();
        AscendC::Duplicate(accLocal, 0.0f, cLen);
        AccumulateWindow(nIdx, od, oh, ow, cBase, cLen, accLocal);
        StoreOutput(outRow, cBase, cLen, divisor, accLocal);
    }

    __aicore__ inline void ProcessOneRow(int outRow)
    {
        const int nIdx = outRow / tiling_.outSpatial;
        const int outRem = outRow - nIdx * tiling_.outSpatial;
        const int od = outRem / tiling_.outHw;
        const int odRem = outRem - od * tiling_.outHw;
        const int oh = odRem / tiling_.OW;
        const int ow = odRem - oh * tiling_.OW;

        const int divisor = ComputeDivisor(od, oh, ow, tiling_);

        for (int cBase = 0; cBase < tiling_.C; cBase += vecLen_) {
            const int remain = tiling_.C - cBase;
            const int cLen = remain < vecLen_ ? remain : vecLen_;
            ProcessOneRowChunk(nIdx, od, oh, ow, outRow, cBase, cLen, divisor);
        }
    }

    AvgPool3DTiling tiling_{};
    AscendC::TPipe *pipe_{nullptr};
    int vecLen_{0};

    AscendC::GlobalTensor<T> xGm_;
    AscendC::GlobalTensor<T> yGm_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> accBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf_;
};

extern "C" __global__ __aicore__ void avg_pool3d(GM_ADDR x, GM_ADDR y, GM_ADDR tiling)
{
    // dtypeKey lives at a fixed offset in the tiling blob; peek it to pick T.
    // (CopyTiling re-reads the full struct inside Init.)
    AvgPool3DTiling peek;
    CopyTiling(&peek, tiling);

    AscendC::TPipe pipe;
    if (peek.dtypeKey == 0) {
        KernelAvgPool3D<float> op;
        op.Init(x, y, tiling, &pipe);
        op.Process();
    } else if (peek.dtypeKey == 1) {
        KernelAvgPool3D<half> op;
        op.Init(x, y, tiling, &pipe);
        op.Process();
    } else {
        KernelAvgPool3D<bfloat16_t> op;
        op.Init(x, y, tiling, &pipe);
        op.Process();
    }
}
