#include <algorithm>

#include "torch_kernel_helper.h"
#include "torch_npu/csrc/core/npu/NPUStream.h"
#include "torch_npu/csrc/core/npu/NPUFormat.h"
#include "tiling/platform/platform_ascendc.h"

#include "op_kernel/avg_pool3d_tiling.h"

#include "aclrtlaunch_avg_pool3d.h"

namespace ascend_kernel {

namespace {

inline int32_t CeilDivI32(int32_t a, int32_t b)
{
    if (b == 0) { return 1; }
    return (a + b - 1) / b;
}

int64_t OutDim(int64_t in, int64_t k, int64_t s, int64_t p, bool ceil_mode)
{
    int64_t o;
    if (!ceil_mode) {
        o = (in + 2 * p - k) / s + 1;
    } else {
        o = (in + 2 * p - k + s - 1) / s + 1;
        if ((o - 1) * s >= in + p) {
            o -= 1;
        }
    }
    return o;
}

struct Pool3dParams {
    int64_t k_d, k_h, k_w;
    int64_t s_d, s_h, s_w;
    int64_t p_d, p_h, p_w;
};

Pool3dParams NormalizeParams(at::IntArrayRef kernel_size, at::IntArrayRef stride,
                             at::IntArrayRef padding)
{
    Pool3dParams p;
    p.k_d = kernel_size[0];
    p.k_h = kernel_size.size() == 1 ? p.k_d : kernel_size[1];
    p.k_w = kernel_size.size() == 1 ? p.k_d : kernel_size[2];

    p.s_d = stride.empty() ? p.k_d : stride[0];
    p.s_h = stride.empty() ? p.k_h : (stride.size() == 1 ? p.s_d : stride[1]);
    p.s_w = stride.empty() ? p.k_w : (stride.size() == 1 ? p.s_d : stride[2]);

    p.p_d = padding.empty() ? 0 : padding[0];
    p.p_h = padding.empty() ? 0 : (padding.size() == 1 ? p.p_d : padding[1]);
    p.p_w = padding.empty() ? 0 : (padding.size() == 1 ? p.p_d : padding[2]);
    return p;
}

int32_t DtypeKey(at::ScalarType st)
{
    if (st == at::kFloat) { return 0; }
    if (st == at::kHalf) { return 1; }
    if (st == at::kBFloat16) { return 2; }
    return -1;
}

}  // namespace

at::Tensor avg_pool3d(const at::Tensor &self, at::IntArrayRef kernel_size, at::IntArrayRef stride,
                      at::IntArrayRef padding, bool ceil_mode, bool count_include_pad,
                      c10::optional<int64_t> divisor_override)
{
    TORCH_CHECK(self.dim() == 5, "avg_pool3d: input must be 5D (N, C, D, H, W)");
    TORCH_CHECK(!kernel_size.empty(), "avg_pool3d: kernel_size must not be empty");

    int32_t dtypeKey = DtypeKey(self.scalar_type());
    TORCH_CHECK(dtypeKey >= 0, "avg_pool3d: only float32/float16/bfloat16 are supported");

    auto pp = NormalizeParams(kernel_size, stride, padding);
    TORCH_CHECK(pp.s_d != 0 && pp.s_h != 0 && pp.s_w != 0, "avg_pool3d: stride must not be zero");

    const int64_t n = self.size(0);
    const int64_t c = self.size(1);
    const int64_t d = self.size(2);
    const int64_t h = self.size(3);
    const int64_t w = self.size(4);

    const int64_t o_d = OutDim(d, pp.k_d, pp.s_d, pp.p_d, ceil_mode);
    const int64_t o_h = OutDim(h, pp.k_h, pp.s_h, pp.p_h, ceil_mode);
    const int64_t o_w = OutDim(w, pp.k_w, pp.s_w, pp.p_w, ceil_mode);

    // NCDHW -> NDHWC so the C channels are contiguous for vectorization.
    at::Tensor x_input = self.permute({0, 2, 3, 4, 1}).contiguous();
    at::Tensor x_flat = x_input.reshape({n * d * h * w, c});

    const int64_t mOut = n * o_d * o_h * o_w;
    at::Tensor y_flat = at::empty({mOut, c}, self.options());

    // Tiling (all int32 fields).
    AvgPool3DTiling tiling{};
    tiling.N = static_cast<int32_t>(n);
    tiling.C = static_cast<int32_t>(c);
    tiling.D = static_cast<int32_t>(d);
    tiling.H = static_cast<int32_t>(h);
    tiling.W = static_cast<int32_t>(w);
    tiling.OD = static_cast<int32_t>(o_d);
    tiling.OH = static_cast<int32_t>(o_h);
    tiling.OW = static_cast<int32_t>(o_w);
    tiling.kD = static_cast<int32_t>(pp.k_d);
    tiling.kH = static_cast<int32_t>(pp.k_h);
    tiling.kW = static_cast<int32_t>(pp.k_w);
    tiling.sD = static_cast<int32_t>(pp.s_d);
    tiling.sH = static_cast<int32_t>(pp.s_h);
    tiling.sW = static_cast<int32_t>(pp.s_w);
    tiling.pD = static_cast<int32_t>(pp.p_d);
    tiling.pH = static_cast<int32_t>(pp.p_h);
    tiling.pW = static_cast<int32_t>(pp.p_w);
    tiling.countIncludePad = count_include_pad ? 1 : 0;
    tiling.divisorOverride = divisor_override.has_value()
        ? static_cast<int32_t>(divisor_override.value()) : 0;
    tiling.inSpatial = static_cast<int32_t>(d * h * w);
    tiling.outSpatial = static_cast<int32_t>(o_d * o_h * o_w);
    tiling.hw = static_cast<int32_t>(h * w);
    tiling.outHw = static_cast<int32_t>(o_h * o_w);
    tiling.vectorLen = static_cast<int32_t>(std::min<int64_t>(c, 256));
    tiling.dtypeKey = dtypeKey;
    tiling.reserved0 = 0;

    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int32_t coreNum = static_cast<int32_t>(ascendc_platform->GetCoreNumAiv());
    if (coreNum <= 0) { coreNum = 1; }
    int32_t mOut32 = static_cast<int32_t>(mOut);
    int32_t usedCoreNum = std::min(coreNum, std::max(mOut32, 1));
    if (usedCoreNum <= 0) { usedCoreNum = 1; }
    tiling.launchBlocks = usedCoreNum;

    at::Tensor tilingCpu = at::empty({static_cast<long>(sizeof(AvgPool3DTiling))},
                                     at::device(at::kCPU).dtype(at::kByte));
    std::memcpy(tilingCpu.data_ptr(), &tiling, sizeof(AvgPool3DTiling));
    at::Tensor tilingNpu = tilingCpu.to(at::kPrivateUse1);

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
    EXEC_KERNEL_CMD(avg_pool3d, blockDim, x_flat, y_flat, tilingNpu);

    // NDHWC -> NCDHW.
    at::Tensor y_ndhwc = y_flat.reshape({n, o_d, o_h, o_w, c});
    at::Tensor y_ncdhw = y_ndhwc.permute({0, 4, 1, 2, 3}).contiguous();
    return y_ncdhw;
}

}  // namespace ascend_kernel
